insert into public.source_observations(source_id,scholarship_id,source_record_key,source_page_url,observed_data,first_seen_at,last_seen_at)
select source.id,scholarship.id,records.source_record_key,records.source_page_url,jsonb_build_object('license','CC-BY-4.0','attribution','Open Scholarships by Grudged LLC','provider_url',records.source_page_url),records.last_verified::timestamptz,now() from records cross join source join public.external_scholarships scholarship on scholarship.canonical_url=records.canonical_url
on conflict(source_id,source_record_key) do update set scholarship_id=excluded.scholarship_id,source_page_url=excluded.source_page_url,observed_data=excluded.observed_data,last_seen_at=excluded.last_seen_at;
